"""Independent audit of the supplied Dabbousi 1997 main article, not a Site importer."""
from pathlib import Path
from datetime import datetime, timezone
import json, hashlib
B=Path(__file__).resolve().parent
PDF=Path(r'[local path redacted]')
SID='dabbousi1997'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def E(p,loc):return {'source_id':SID,'pdf_page':p,'printed_page':9462+p,'locator':loc}
def I(id,text,p,loc,claim='reported_experiment',**kw):
 return dict(id=id,text=text,claim_type=claim,evidence=[E(p,loc)],**kw)
def plus(item,p,loc):item['evidence'].append(E(p,loc));return item

