cohorts=[
 I('size_series_F1_F2','Bare and 1–2 monolayer ZnS-overcoated size series: a23 Å,b42 Å,c48 Å,d55 Å core diameters. Figure2 shell-coated room-temperature PL yields40%,50%,35%,30%, respectively. Bare dots mean organic TOPO/TOP caps. Exact layer coverage and complete shell recipe for each size are not enumerated.',3,'Figures1 and2',quantities={'rows':[{'label':a,'core_diameter_A':d,'coated_PL_yield_percent':y} for a,d,y in [('a',23,40),('b',42,50),('c',48,35),('d',55,30)]]}),
 I('photograph_F3','Six hexane dispersions in matching quartz cuvettes illuminated with365 nm UV. Left-to-right PL peaks470,480,520,560,594,620 nm. These six specimens are not mapped by the paper to all four Figure1/2 specimens. Supplied reproduction is grayscale, despite color-photo caption.',4,'Figure3 and discussion',quantities={'excitation_nm':365,'PL_peak_nm':[470,480,520,560,594,620]}),
 I('main_coverage_series','Main split-core series: approximately40 Å body,42 Å±10% optical/SAXS labels; TEM bare major diameter39 Å±8.2%. Coverage labels0,.65,1.3,2.6,5.3 monolayers derive from TEM major-axis growth. Use method-specific size fields rather than choosing one as universally exact. Figures4,5,8,9,10,13 and Table1 describe this coverage progression.',4,'Figures4/5 and body',quantities={'coverage_monolayers':[0,0.65,1.3,2.6,5.3]}),
 I('xps_cohorts','XPS examines multiple approximately33 and40 Å core samples with variable shells. Figure6 explicitly compares approximately40 Å bare with approximately1.3 monolayers; Figure7 compares bare,.65,1.3,2.6 monolayers. Do not automatically assign each XPS result to an identical physical TEM/optical aliquot.',5,'XPS Results and Figure6'),
 I('oxidized_bare_xps','Bare-dot air-exposure series: initial Se/Cd~.87 (46%Se/54%Cd);16 h Se/Cd.77 (43/57) and SeO2 peak13% total Se;80 h Se/Cd.37 (28/72),SeO2 peak22%. Different numbers are whole measured signals, not shell stoichiometry or direct synthesis yield.',6,'XPS air-exposure Results',quantities={'rows':[{'time_h':0,'Se_Cd':0.87,'Se_percent':46,'Cd_percent':54,'SeO2_signal_percent':None},{'time_h':16,'Se_Cd':0.77,'Se_percent':43,'Cd_percent':57,'SeO2_signal_percent':13},{'time_h':80,'Se_Cd':0.37,'Se_percent':28,'Cd_percent':72,'SeO2_signal_percent':22}],'time_zero_basis':'initial baseline, not a reported precisely zero-air-exposure specimen'}),
 I('solution_saxs_F11_F12','Independent dilute-hexane SAXS cohort explicitly has different Zn/Cd ratios than Table1 and must not be merged with it. Bare caption42 Å; coated ratios.42,.85,3.1; highest ratio5.3 in Figure11/p9 versus5.6 in p8. Bare fitted R0≈19.50 Å,σ≈.12 in text; Figure12captionσ=.11,.14,.16,.25 for a–d. Higher-coverage fits are described as unreliable, so quoted captionσ does not certify reliable mean sizes.',8,'Figures11/12 discussion',quantities={'ratio_labels':[0,0.42,0.85,3.1],'highest_ratio_reports':[5.3,5.6],'bare_fitted_radius_A':19.50,'bare_sigma_body':0.12,'sigma_caption_a_to_d':[0.11,0.14,0.16,0.25]}),
 I('theory_F14','Figure14 is calculated radial probability and band-offset diagrams, not measured atomic or carrier-density data. Body says20 Å core radius, caption20 Å diameter; shells4 Å ZnS orCdS. Preserve source conflict and do not train an exact geometry label from it.',11,'Figure14 and body','author_model',quantities={'core_size_number_A':20,'core_size_definition_conflict':['radius','diameter'],'shell_A':4}),
 I('zns_shift_F15','Approximately20 Å radius CdSe cores overcoated with ZnS: measured absorption and PL energy shifts versus shell thickness with model curves. PL excitation450 nm. Largest body-reported absorption redshift~36 meV at16 Å ZnS. Figure15 is not a tabulated raw-data series; do not invent intermediate point coordinates.',11,'Figure15 and discussion',quantities={'core_radius_A':20,'PL_excitation_nm':450,'largest_shell_A':16,'absorption_shift_magnitude_meV':36}),
 I('cds_shift_F16','CdS overcoating comparison has inconsistent core-size wording: experimental33.5–35 Å diameter;p11~30 Å radius;Figure16caption andp12~16 Å radius. Body reports~210 meV shift for15 Å CdS on~16 Å radius core. Error bars inFigure16 represent TEM size distribution, not energy uncertainty. Plot model curves and the source-label conflict remain separate.',12,'Figure16 and discussion',quantities={'body_shell_A':15,'body_core_radius_A':16,'shift_magnitude_meV':210})
]
