rows=[]
for coverage,tem,spread,aspect,saxs,sp,wd,sr,wr in [(0,39,8.2,1.12,42,10,None,None,None),(.65,43,11,1.16,46,13,.46,.58,.7),(1.3,47,10,1.16,50,18,1.50,1.32,1.4),(2.6,55,13,1.23,None,None,3.60,None,2.9),(5.3,72,19,1.23,None,None,6.80,None,6.8)]:
 rows.append(dict(TEM_derived_coverage_monolayers=coverage,TEM_major_axis_A=tem,TEM_relative_size_spread_percent=spread,TEM_average_aspect_ratio=aspect,SAXS_polymer_fitted_size_A=saxs,SAXS_polymer_fitted_spread_percent=sp,WDS_measured_Zn_Cd=wd,SAXS_polymer_calculated_Zn_Cd=sr,WAXS_calculated_Zn_Cd=wr))
tables=[I('table1','All table cells visually checked. Empty cells are null (not zero). TEM sizes are longest-axis means; ±percent entries describe size distributions. SAXS and WAXS columns are calculated/fitted results distinct from WDS measured compositions. Coverage is TEM-derived, not precursor dose.',5,'Table1','mixed_reported_and_author_derived',rows=rows)]

observations=[
 I('scope_performance','Study-level core diameters23–55 Å, room-temperature PL30–50%, linewidth fwhm≤40 nm and emission spanning approximately470–625 nm. These are summary ranges, not labels applying identically to every specimen.',1,'Abstract and Introduction',quantities={'diameter_A':[23,55],'PL_yield_percent':[30,50],'fwhm_nm':{'qualifier':'less_than_or_equal','value':40},'emission_span_nm':[470,625]}),
 I('bare_surface','Bare dots throughout the paper remain TOPO/TOP capped; core/shell dots also retain organic caps after ZnS growth. Pyridine exchange is a later specimen or dispersion preparation.',3,'III.A Synthesis'),
 I('temperature_tradeoff','Excessive overgrowth temperature causes core Ostwald ripening and broader distributions; too low can leave precursor decomposition incomplete or reduce shell crystallinity. Temperature is optimized independently for each core size.',3,'III.A Synthesis','author_interpretation'),
 I('slow_feed','Low concentration and slow addition favor growth on seeds over separate ZnS nucleation, but authors explicitly do not claim to eliminate separate small ZnS particles. Final size selection offers further assurance.',3,'III.A Synthesis','author_interpretation'),
 I('monolayer_definition','One ZnS monolayer is3.1 Å, distance between consecutive planes along bulk-wurtzite [002], measured along the prolate-particle major axis. TEM-derived coverage is not a direct assertion of uniform isotropic shell thickness.',3,'III.B Optical Characterization',quantities={'monolayer_major_axis_thickness_A':3.1}),
 I('size_series_spectra','Coating broadens and redshifts absorption; smaller cores show stronger shift, interpreted as exciton leakage into ZnS. Bare PL yields generally5–15% become30–50%; deep-trap emission of small bare cores is suppressed, producing stronger band-edge emission.',4,'Optical Characterization','author_interpretation',quantities={'bare_PL_percent':[5,15],'coated_PL_percent':[30,50]}),
 I('coverage_spectra','The main shell series uses equal area under the lowest absorption feature as constant oscillator strength. Increasing shell shifts absorption/PL red, broadens the distributions and increases ultraviolet absorption into ZnS. These are spectral normalization and interpretation, not constant synthesis concentration measurements.',4,'Figure4 discussion','author_interpretation'),
 I('coverage_PL_maximum','For the main series, yield begins15% bare, approaches50% near1.3 monolayers, then falls to30% at approximately5 monolayers. Intermediate inset points are plotted but not numerically tabulated; do not pretend exact point extraction.',5,'Figure5 and discussion',quantities={'bare_yield_percent':15,'maximum_yield_percent':50,'maximum_coverage_ML':1.3,'high_coverage_yield_percent':30,'high_coverage_ML_approx':5}),
 I('wds_cd_rich','WDS consistently measures Se/Cd approximately0.8–0.9/1 for bare dots, interpreted as Cd-rich nanoparticles. This is distinct from each Zn/Cd shell ratio.',5,'WDS Results',quantities={'Se_Cd':[0.8,0.9]}),
 I('xps_contamination_ligands','XPS C/O signals are attributed mainly to approximately15 min air exposure and have adsorbate-like energies, suggesting no significant charging. Residual P remains after pyridine exchange, indicating bound TOP/TOPO; do not import Danek below-detection P result.',5,'XPS Results','author_interpretation'),
 I('xps_sensitivity_correction','Relative Cd/Se peak areas are divided by sensitivity factors and corrected for finite-particle escape-depth attenuation, integrating exp(-z/λ) over a sphere. InitialSe/Cd~.87 (46%Se/54%Cd) agrees with WDS. The correction is a model, not an extra precursor quantity.',5,'XPS Results','author_model'),
 I('auger_parameters','Cd Auger parameter for bare and coated dots466.8±.2 eV agrees with bulkCdSe; Zn parameter757.5 eV for1.3/2.6 monolayer samples is compared with expected758.0 eV. Reference758.0 is not a second sample measurement.',6,'XPS Results',quantities={'Cd_parameter_eV':466.8,'Cd_uncertainty_eV':0.2,'Zn_parameter_eV':757.5,'Zn_bulk_comparison_eV':758.0}),
 I('oxidation_coverage','SeO2 peak at59 eV appears after80 h for bare and.65ML specimens. At estimated~1.3ML or more oxide is absent on prolonged air exposure; another sentence says >1.3ML Se/Cd unchanged after80 h. This supports possibly continuous passivation, not exact coverage of every site.',6,'XPS Results','author_interpretation',quantities={'oxide_binding_energy_eV':59,'exposure_h':80,'threshold_ML_approx':1.3}),
 I('oxidation_surface_account','For~40 Å dots the estimated surface-atom fraction34% is used to infer that much surface Se has desorbed after80 h. No Cd–O peak is seen, but bare Cd Auger parameter changes466.8→467.5 eV;1.3/2.6ML coated values remain unchanged. Surface fraction is calculated context, not a measured yield.',6,'XPS Results','mixed_reported_and_author_derived',quantities={'estimated_surface_atoms_percent':34,'bare_Cd_parameter_before_eV':466.8,'bare_Cd_parameter_after80h_eV':467.5}),
 I('xps_auger_attenuation','Normalized XPS-to-Auger Cd intensity ratio increases for a shell because Cd Auger electrons have shorter escape depths. Reported calculated normalized ratios1.28 and1.60 for.65 and2.6ML support surface-localized ZnS; they are not Zn/Cd composition ratios.',6,'Equation1 discussion','author_derived',quantities={'rows':[{'coverage_ML':.65,'normalized_XPS_Auger_ratio':1.28},{'coverage_ML':2.6,'normalized_XPS_Auger_ratio':1.60}]}),
 I('escape_depths','Experimental note26 supplies electron escape depths used in XPS analysis; these are analytical constants, not measured shell thicknesses.',13,'Reference/note26','methodological_reference',quantities={'escape_depth_A':{'CdSe':{'Cd3d':15,'CdAuger':10,'Se3d':21},'ZnS':{'Cd3d':23.7,'CdAuger':13.2,'Se3d':31.2,'Zn2p':9.6,'ZnAuger':26.8,'S2p':28.9}}}),
 I('tem_structure','Lattice fringes extend through a2.6ML particle and suggest epitaxy, but no resolved core/shell interface is observed. Unusual bending in Figure8B may indicate strain; most fringes are straight. At high coverage some patchy growth/misshapen particles occur, without observed tethered separate ZnS nuclei.',6,'TEM Results','author_interpretation'),
 I('saxs_polymer_trend','Increasing shell shifts SAXS ringing to smaller angles; low coverage0–1.3ML retains structure. Above~2.5ML structure is sparse;2.6/5.3ML main-series curves cannot be fitted confidently. Other >3ML samples also give structureless curves.',7,'SAXS in Polymer Films','author_interpretation'),
 I('polymer_saxs_model','Use discrete Debye scattering from wurtzite atoms retained inside ellipsoidal core/shell outlines. Dimensions and aspect distributions come from TEM; hold core size/distribution/aspect fixed while fitting shell size/spread. A shape distribution barely changes curves but substantially improves predicted Zn/Cd agreement with WDS.',7,'Equation2 and polymer SAXS model','author_model'),
 I('shape_weight_example','Illustrative20 Å radius particle/aspect1.2 curve is similar to weighted20 Å radius curves with aspect1.1/1.2/1.3/1.4 at24/36/24/16%. This is an explanatory model example, not four independent synthesized populations with measured fractions.',7,'SAXS model example','author_model',quantities={'radius_A':20,'aspect_ratios':[1.1,1.2,1.3,1.4],'weights_percent':[24,36,24,16]}),
 I('polymer_aggregation','Shoulder below2θ~2° indicates aggregation, attributed to poor ZnS/TOPO passivation and irreversible flocculation during repeated size selection. MTD300P20 is only slightly better than PVB; preparing films under inert atmosphere does not improve separation. Below~2.5° unsuitable for fitting but ringing position/size estimate is less affected.',7,'Polymer SAXS aggregation discussion','author_interpretation'),
 I('solution_saxs_analysis','Analyze background-subtracted intensity with Guinier/Porod plots and log-normal or Gaussian radius distributions. Comparable low particle concentrations isolate form-factor effects. I(0) scales approximatelyN R^6; nonlinearity at high coverage is attributed to polydispersity, although attractive interactions could also produce it.',8,'Solution SAXS analysis','author_model'),
 I('solution_saxs_upper_bounds','Bare R0≈19.50 Å and σ≈.12 are fitted away from origin. High-coverage data lack reliable average-size/variance fits; instead authors derive upper-distribution radii from the sixth root of intensity ratios and restricted low-q extrapolation. No numerical table of those upper radii is given.',9,'Solution SAXS fitting','author_derived'),
 I('density_model_error','Assuming one core/shell electron density neglects CdSe~2.92 versusZnS~2.35 e/Å³ and incurs estimated10–15% size error. This is a systematic model assumption, not each TEM measurement uncertainty.',9,'Solution SAXS density approximation','author_model',quantities={'CdSe_e_A3':2.92,'ZnS_e_A3':2.35,'estimated_size_error_percent':[10,15]}),
 I('waxs_features','Bare broad feature combines(100),(002),(101); reduced(102)/(103) is assigned to [002] stacking faults. Coating shifts/broadens the first feature~26°, decreases(102)~36°, changes peaks~47°, and at high coverage adds~56° peak. These are approximate plot angles; Figure13axis2θ differs from the text simulation interval labelledθ.',10,'WAXS Results','author_interpretation',quantities={'approx_peak_angles_deg':[26,36,47,56]}),
 I('waxs_core_model','Bare WAXS model: average1.4 stacking faults/crystallite, prolate~1200-atom core, aspect1.1. Later model paragraph says CdSe aspect1.15. These are model settings, not measured atom counts or a unified exact aspect ratio; fixed core settings carry into shell simulations.',10,'WAXS model','author_model',quantities={'core_stacking_faults':1.4,'core_atoms_approx':1200,'core_aspect_reports':[1.1,1.15]}),
 I('waxs_lattice_model','At2.6/5.3ML, reasonable fits require bulk lattice parameters aCdSe4.29 Å,aZnS3.82 Å; small-coverage ZnS parameter weakly affects fit. ZnS first-feature scattering area estimated~3-fold weaker than CdSe; heavy coverage is needed to resolve shell structure. These bulk-valued fit choices are not a deposited-CIF refinement.',10,'WAXS model','author_model',quantities={'a_CdSe_A':4.29,'a_ZnS_A':3.82,'first_feature_CdSe_ZnS_area_ratio_approx':3}),
 I('waxs_shell_model','Shell aspect distribution weighted1.2–1.4 from TEM, biased toward large values at high coverage. Highest coverage best fit uses3 shell stacking faults/crystallite. Other shells contribute too little for reliable fault inference. ModelZn/Cd=.7,1.4,2.9,6.8 as inTable1.',10,'WAXS model','author_model',quantities={'shell_aspect_range':[1.2,1.4],'highest_shell_faults':3,'model_Zn_Cd':[.7,1.4,2.9,6.8]}),
 I('waxs_interface_limit','Rotating shell(100) to core(101) does not significantly improve the highest-coverage fit. Including or omitting cross-material pair terms(Cd–S,Zn–Se,S–Se,Cd–Zn) modifies scattering less than changing composition, aspect or fault density. Interface orientation/atomic positions are not uniquely solved.',10,'WAXS interface sensitivity','author_model'),
 I('electronic_model','Noninteracting charge carriers in a spherical core/concentric shell without interfacial alloying, with Coulomb attraction as first-order perturbation. ZnS electron/hole barriers.9 eV each; organic electron/hole barriers4/10 eV are fitted phenomenological parameters, explicitly not literal band-offset measurements.',10,'IV.A Electronic structure','author_model',quantities={'ZnS_electron_barrier_eV':.9,'ZnS_hole_barrier_eV':.9,'organic_electron_barrier_eV':4,'organic_hole_barrier_eV':10}),
 I('cds_barriers','CdS model electron barrier.2 eV permits greater delocalization; hole barrier.55 eV permits more penetration than ZnS but less than electron. These are model parameters/context, not measured synthesis activation barriers.',11,'Electronic structure discussion','author_model',quantities={'CdS_electron_barrier_eV':.2,'CdS_hole_barrier_eV':.55}),
 I('model_wavefunction_trend','Bare light-electron wavefunction spans the core, heavier hole is central; ZnS mainly lets electron leak outward, lowering confinement until saturation. CdS allows substantially more electron leakage and hence larger absorption redshifts. Figure14 is a schematic calculated model.',11,'Figure14 discussion','author_model'),
 I('pl_shift_weighting','PL shifts exceed absorption shifts increasingly at high coverage; authors attribute much of it to broadening and preferential excitation of larger dots. Figure15 excitation450 nm is described as~100 nm blue of first absorption. Note38 converts absorption linewidth to an effective bare-dot distribution and weights by effective radius cubed(volume).',11,'Figure15 discussion','author_model'),
 I('same_material_counterfactual','ObservedZnS16 Å shell/~20 Å radius core gives~36 meV shift; hypothetical CdSe shell of same thickness/core would yield~290 meV. ObservedCdS15 Å/~16 Å core gives~210 meV; hypotheticalCdSe15 Å would yield~390 meV. The CdSe-shell values are counterfactual model comparisons, not extra shell-synthesis recipes.',12,'Discussion first paragraph','mixed_reported_and_author_model',quantities={'observed_ZnS_shift_meV':36,'hypothetical_CdSe16A_shift_meV':290,'observed_CdS_shift_meV':210,'hypothetical_CdSe15A_shift_meV':390}),
 I('passivation_PL_link','The maximum~50% yield near1.3ML coincides with first tested coverage lacking Se oxide after80h, suggesting most vacancy/nonradiative sites are passivated. This is a cohort correlation, not proof all surfaces or samples share an exact universal optimum.',12,'IV.B shell and yield','author_interpretation'),
 I('thick_shell_decline','Higher coverage favors [002] elongation, nonuniform morphology and irreversible flocculation; inferred weak ligand binding and modeled stacking faults may create nonradiative sites and lower PL yield. Defect mechanism remains inferred rather than atomically localized.',12,'IV.B shell and yield','author_interpretation'),
 I('growth_mechanism_options','Data are interpreted as local/coherent epitaxy at low coverage and epitaxial but incoherent growth above~2ML. TEM cannot resolve lattice-spacing difference or out-of-plane defects, while WAXS is orientation-insensitive. Two proposed mechanisms are coherent growth relaxing via dislocations/grain boundaries, or coherent islands coalescing with grain boundaries.',12,'IV.B growth mechanism','author_interpretation'),
 I('mismatch_comparison','CdSe/ZnS mismatch~12% is used to motivate strain relaxation. The cited CdSe/ZnSe quantum-well comparison has7% mismatch and diminished PL above4 CdSe monolayers; those values describe reference40, not the current nanocrystal critical thickness.',12,'Growth-mechanism comparison','citation_context',quantities={'current_pair_mismatch_percent':12,'cited_quantum_well_mismatch_percent':7,'cited_quantum_well_CdSe_threshold_ML':4})
]
plus(observations[32],13,'Reference/model note38')

