equations=[
 I('eq1','I=J0 N(z)i σi Yi,n F(KE) exp[-z/λ(KE)] describes depth-dependent XPS/Auger intensity. Subsequent same-atom ratios cancel flux, population and absorption cross section.',6,'Equation1','author_model'),
 I('eq2','Discrete Debye form I(q)=I0[f²(q)/q] sum_k[ρ(rk)/rk sin(q rk)], with q=4πsinθ/λ. Applied to generated wurtzite ellipsoids for SAXS and WAXS. Preserve source mathematical notation; not a DFT result.',7,'Equation2','author_model'),
 I('eq3','Zero-angle contrast integral I(0)=integral_0^infinity4πr²Δρ_tilde²(r)dr=N(v<Δρ>)² approximatelyNR^6. Used with comparable particle concentrations; density differences and polydispersity limit inferred sizes.',8,'Equation3','author_model'),
 I('eq4','Radial-wavefunction continuity at the core/shell radius: R1S,CdSe(k1r1)=R1S,ZnS(kappa2r1).',10,'Equation4','author_model'),
 I('eq5','Continuity of inverse-effective-mass-weighted radial derivative at r1. This probability-current boundary condition uses bulk effective masses without listing their numerical values.',11,'Equation5','author_model'),
 I('unnumbered_guinier','Printed Guinier expression uses I(q,N)≈I(0,N)exp(-q²RG²/5), describing RG as Guinier radius for spheres. Preserve the printed factor/definition rather than silently replacing by another convention.',8,'Solution SAXS Guinier expression','author_model'),
 I('unnumbered_radius_ratio','R≈R0m[Inm(0)/I0m(0)]^(1/6) yields effective/upper radii from zero-angle intensities; high-coverage values are upper-distribution estimates, not means.',9,'Solution SAXS extrapolation','author_model'),
 I('unnumbered_xps_ratio','Normalize the Cd photoelectron/Auger intensity ratio of a coated specimen by that of bareCdSe; this ratio is not elemental Zn/Cd stoichiometry.',6,'After Equation1','author_model'),
 I('unnumbered_escape_correction','Finite-size XPS sensitivity uses an integral of exp(-z/λ), evaluated over spherical nanocrystal geometry; not an independently measured shape proof.',5,'XPS sensitivity correction','author_model')]

conflicts=[
 I('c_core40_42_39','Main-series approximate40Å body,42Å±10% optical/SAXS and39Å±8.2%TEM describe method-specific size estimates; preserve their definitions and errors. Note22 specifies40Å→180°C, not42Å.',5,'Table1 and Figure5','ambiguity',resolution='Do not replace source sizes with a single averaged/exact size.'),
 I('c_saxs5p3_5p6','Highest independent solution-SAXS Zn/Cd ratio is5.3 inFigure11caption andp9 but5.6 in p8Guinier discussion.',8,'Figure11 caption and body','source_conflict',resolution='Keep both reports, exclude exact-ratio conditioning pending resolution.'),
 I('c_sigma','Bare solution-SAXS σ≈.12 in p9body versus.11 inFigure12caption.',9,'Figure12 and following text','source_conflict',resolution='Keep source-labelled fit values, do not silently choose.'),
 I('c_high_saxs_fit','Figure12caption givesσ=.25 for d while text says high-coverage data cannot yield meaningful average/variance fits. These may be illustrative rather than reliable fits.',9,'Figure12 and fitting discussion','source_tension',resolution='Preserve caption value only as model context with reliability limitation.'),
 I('c_F14_core','Figure14caption says20Ådiameter while body says~20Åradius; plotted core boundary around20Å fromcenter aligns with radius interpretation but is not authority to erase caption.',11,'Figure14 and body','source_conflict',resolution='Keep model geometry conflict explicit; no exactstructure training label.'),
 I('c_CdS_core','Experimental CdS cores33.5–35Ådiameter;p11Fig16discussion~30Åradius;Fig16caption/p12body~16Åradius. Different-sample possibility is not resolved.',11,'Figure16 discussion','source_conflict',resolution='Do not merge exact core-size labels across these passages.'),
 I('c_F16_barrier','Figure16caption calls4eV/10eV the barriers into surrounding CdS matrix; electronic-model body assigns4/10eV to organic matrix, andCdS barriers.2/.55eV.',12,'Figure16 caption','source_conflict',resolution='Retain caption conflict and distinguish actual model-region parameters.'),
 I('c_detector_distance','Experimental SAXS says detector placed atD370mm from the detector. This is self-referential wording.',3,'SAXS in Dilute Solutions','source_ambiguity',resolution='Report D370mm with endpoints unresolved; do not manufacture sample-distance definition.'),
 I('c_theta','WAXS text simulation interval15°<θ<60° while Figure13axis is2θ; the plotted feature positions use26/36/47/56°.',10,'WAXS simulation;Figure13 onp9','notation_ambiguity',resolution='Preserve stated angle labels; do not convert all values without resolving convention.'),
 I('c_model_aspect','WAXS bare-core model aspect1.1 early paragraph versus1.15 later;Table1TEMmean1.12. These are model descriptions and a distinct measured mean.',10,'WAXS model','source_ambiguity',resolution='Do not equate or average the three values.'),
 I('c_photo_color','Figure3caption calls color photograph, but supplied PDF visibly provides grayscale cuvettes.',4,'Figure3','source_asset_limitation',resolution='Use original grayscale; retain textual wavelength/color explanation without invented source colors.'),
 I('c_nominal_actual','Geometric precursor target, actualWDSZn/Cd, TEM-derivedshellcoverage, SAXS-fitcomposition andWAXS-fitcomposition are different quantities; incorporation is lower than precursoraddition.',2,'Synthesis and Table1','semantic_hazard',resolution='Keep separate dose/measurement/model fields.'),
 I('c_cds_storage_equal','Equal amounts hexane/butanol forCdSstorage lacks unit basis or absolute quantities.',2,'(CdSe)CdS method','missingness',resolution='Do not infer5mL each or a measured 1:1 volume ratio.'),
 I('c_monolayer_geometry','Shell monolayer is3.1Å along majoraxis while precursor-dose model assumes sphericalgeometry; realhighcoverage particles areprolate/nonuniform.',3,'Monolayerdefinition;Synthesisp2','semantic_hazard',resolution='Do not generate an experimentally validated uniform concentricatomic shell.'),
 I('c_oxidation_threshold','Oxide absence stated~1.3MLormore, unchangedSe/Cdratio statedmorethan1.3ML, and1.3/2.6MLAuger parametersunchanged.',6,'XPS oxidation discussion','source_wording_limit',resolution='Preserve individual observation thresholds; no universal exact protective threshold.'),
 I('c_model_counterfactual','Hypothetical16/15ÅCdSe shells with290/390meVshifts are counterfactual modelcomparisons, not extraexperimentallysynthesizedmaterial records.',12,'Discussion first paragraph','semantic_hazard',resolution='Reader/modelcontext only.'),
 I('c_prior_film_devices','Introduction~10%ES-OMCVDfilmPL and cathodoluminescence refer toreference21;LEDproposals reference20 manuscripts. They are not synthesis/measurements performed and fully specified inthisarticle.',1,'Introduction','citation_scope',resolution='Referencecontextonly, no inventedfilmrecipe.')]
